describe('Cookie Consent Banner', () => {
    beforeEach(() => {
        cy.visit('https://example.com'); // Replace with the actual URL of the application
    });

    it('should disappear after accepting the cookie consent', () => {
        cy.get('.cookie-consent-banner').should('be.visible');
        cy.get('.accept-cookies-button').click();
        cy.get('.cookie-consent-banner').should('not.exist');
    });

    it('should remain visible if the user does not accept', () => {
        cy.get('.cookie-consent-banner').should('be.visible');
        cy.get('.decline-cookies-button').click();
        cy.get('.cookie-consent-banner').should('be.visible');
    });
});
